std::array<int16_t, 3> MappingZones::rootAndRangeForPosition(const juce::Point<int> &p)
{
    assert(lastMidiNote > firstMidiNote);
    auto lb = getLocalBounds().toFloat();
    auto kw = lb.getWidth() / (lastMidiNote - firstMidiNote);

    auto rootKey =
        std::clamp(p.getX() * 1.f / kw + firstMidiNote, (float)firstMidiNote, (float)lastMidiNote);

    auto fromTop = std::clamp(p.getY(), 0, getHeight()) * 1.f / getHeight();
    auto span = (1.0f - fromTop) * 80 + 1;
    auto low = std::clamp(rootKey - span, 0.f, 127.f);
    auto high = std::clamp(rootKey + span, 0.f, 127.f);
    return {(int16_t)rootKey, (int16_t)low, (int16_t)high};
}

void MappingDisplay::componentMovedOrResized(juce::Component &c, bool wasMoved, bool wasResized)
{
    if (isUpdatingComponents || !keyboardViewport || !zonesViewport)
        return;
    isUpdatingComponents = true;

    auto zvp = zonesViewport->viewport.get();
    auto kvp = keyboardViewport->viewport.get();
    auto zvc = zonesViewport->getViewedComponent();
    auto kvc = keyboardViewport->getViewedComponent();

    auto fromZones = (&c == zvc || &c == zvp || &c == zonesViewport.get());
    auto fromKeyboard = (&c == kvc || &c == kvp || &c == keyboardViewport.get());

    auto &zz = zonesViewport->zoomX;
    auto &kz = keyboardViewport->zoomX;

    if (fromZones && zz.val != kz.val)
    {
        kz.val = zz.val;
        auto w = kvp->getWidth() * kz.val - kvp->getScrollBarThickness();
        auto h = kvp->getHeight() * keyboardViewport->zoomY.val - kvp->getScrollBarThickness();
        kvc->setBounds(kvc->getX(), kvc->getY(), w, h);
    }
    else if (fromKeyboard && zz.val != kz.val)
    {
        zz.val = kz.val;
        auto w = zvp->getWidth() * zz.val - zvp->getScrollBarThickness();
        auto h = zvp->getHeight() * zonesViewport->zoomY.val - zvp->getScrollBarThickness();
        zvc->setBounds(zvc->getX(), zvc->getY(), w, h);
    }

    if (fromZones)
    {
        kvp->setViewPosition(zvp->getViewPositionX(), kvp->getViewPositionY());
    }
    else if (fromKeyboard)
    {
        zvp->setViewPosition(kvp->getViewPositionX(), zvp->getViewPositionY());
    }

    isUpdatingComponents = false;
}

