#ifndef SCXT_SRC_MODULATION_MODULATORS_CURVELFO_H
#define SCXT_SRC_MODULATION_MODULATORS_CURVELFO_H

namespace scxt::modulation::modulators
{
struct CurveLFOStorage
{
    float deform{0.f};
    float amplitude{1.f};

    float delay{0.f}, attack{0.f}, hold{0.f}, decay{0.f}, sustain{0.f}, release{0.f};
    bool unipolar{false};

    bool operator==(const CurveLFOStorage &other) const
    {
        return deform == other.deform && amplitude == other.amplitude && delay == other.delay &&
               attack == other.attack && hold == other.hold && decay == other.decay &&
               sustain == other.sustain && release == other.release && unipolar == other.unipolar;
    }
    bool operator!=(const CurveLFOStorage &other) const { return !(*this == other); }
};
} // namespace scxt::modulation::modulators

#endif // SCXT_SRC_MODULATION_MODULATORS_CURVELFO_H

