struct ModulatorStorage
{
    enum ModulatorShape
    {
        STEP,

        LFO_SINE,
        LFO_RAMP,
        LFO_TRI,
        LFO_PULSE,
        LFO_SMOOTH_NOISE,
        LFO_SH_NOISE,
        LFO_ENV,

        MSEG,
    } modulatorShape{ModulatorShape::STEP};
