    {
        return modulatorShape == other.modulatorShape && triggerMode == other.triggerMode &&
               rate == other.rate && start_phase == other.start_phase && temposync == other.temposync &&
               stepLfoStorage == other.stepLfoStorage && curveLfoStorage == other.curveLfoStorage;
