std::string ModulatorStorage::toStringModulatorShape(const ModulatorShape &ms)
{
    switch (ms)
    {
    case STEP:
        return "step";
    case LFO_SINE:
        return "lsine";
    case LFO_RAMP:
        return "lramp";
    case LFO_TRI:
        return "ltri";
    case LFO_PULSE:
        return "lpulse";
    case LFO_SMOOTH_NOISE:
        return "lnoise";
    case LFO_SH_NOISE:
        return "lshn";
    case LFO_ENV:
        return "lenv";
    case MSEG:
        return "mseg";
    }
    return "ERROR";
}

ModulatorStorage::ModulatorShape ModulatorStorage::fromStringModulatorShape(const std::string &s)
{
    static auto inverse =
        makeEnumInverse<ModulatorStorage::ModulatorShape, ModulatorStorage::toStringModulatorShape>(
            ModulatorShape::STEP, ModulatorStorage::MSEG);
    auto p = inverse.find(s);
    if (p == inverse.end())
        return STEP;
    return p->second;
}
std::string ModulatorStorage::toStringTriggerMode(const TriggerMode &tm)
{
    switch (tm)
    {
    case KEYTRIGGER:
        return "kt";
    case FREERUN:
        return "free";
    case RANDOM:
        return "rnd";
    case RELEASE:
        return "rel";
    case ONESHOT:
        return "ones";
    }
    return "ERROR";
}

ModulatorStorage::TriggerMode ModulatorStorage::fromStringTriggerMode(const std::string &s)
{
    static auto inverse =
        makeEnumInverse<ModulatorStorage::TriggerMode, ModulatorStorage::toStringTriggerMode>(
            TriggerMode::KEYTRIGGER, TriggerMode::ONESHOT);
    auto p = inverse.find(s);
    if (p == inverse.end())
        return KEYTRIGGER;
    return p->second;
}
} // namespace scxt::modulation

